        [Fact]
        public void PromptTextAndSchemasMatchPython()
        {
            Assert.Equal("You are a cook.\n\nReply with exactly one JSON object and nothing else. The object is one of:\n  {\"tool\": \"<name>\", \"args\": {...}}   call one tool\n  {\"final\": \"<one spoken line>\"}       say a last line and stop\n  {\"done\": true}                       stop; nothing more to do\n\nTools:\n- say(line): Say a line.\n    line: short text, at most 60 characters\n- remember(fact, importance): Store a fact.\n    fact: short text, at most 200 characters\n    importance: one of: \"not important\" | \"kind of important\" | \"fairly important\" | \"very important\" | \"critical\"\n- set_mood(target, delta): Feelings.\n    target: one of: \"Pip\" | \"Lux\"\n    delta: one of: \"much worse\" | \"worse\" | \"a little worse\" | \"no change\" | \"a little better\" | \"better\" | \"much better\"\n- count(n): A number.\n    n: a whole number from 1 to 5\n- do_nothing(): Nothing.", Prompt.RenderSystem("  You are a cook.\n ", Fx.Tools()));
            Assert.Equal("x\n\nReply with exactly one JSON object and nothing else. The object is one of:\n  {\"tool\": \"<name>\", \"args\": {...}}   call one tool\n  {\"final\": \"<one spoken line>\"}       say a last line and stop\n  {\"done\": true}                       stop; nothing more to do\n\nTools:\n- pick(who, size, mood?, note?, big?): Pick \"one\"; \\ here.\n    who: who; one of: \"Pip\" | \"Lux \"the\" fox\" | \"Zo\u00eb\\x\" | \"\u65e5\u672c\"\n    size: a whole number from -5 to 60\n    mood: one of: \"so-so\" | \"grand\"\n    note: a note; short text, at most 7 characters\n    big: a whole number from 0 to 39", Prompt.RenderSystem("x", Fx.OddTools()));
            Assert.Equal("x\n\nReply with exactly one JSON object and nothing else. The object is one of:\n  {\"tool\": \"<name>\", \"args\": {...}}   call one tool\n  {\"final\": \"<one spoken line>\"}       say a last line and stop\n  {\"done\": true}                       stop; nothing more to do\n\nTools:", Prompt.RenderSystem("x", new List<ToolSpec>()));
            Assert.Equal("{\"type\":\"function\",\"function\":{\"name\":\"say\",\"description\":\"Say a line.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"line\":{\"type\":\"string\",\"maxLength\":60,\"minLength\":1}},\"required\":[\"line\"],\"additionalProperties\":false}}}", PyJson.Compact(Fx.Tools()[0].OpenAiTool()));
            Assert.Equal("say(line)", Fx.Tools()[0].Signature());
            Assert.Equal("{\"type\":\"function\",\"function\":{\"name\":\"remember\",\"description\":\"Store a fact.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"fact\":{\"type\":\"string\",\"maxLength\":200,\"minLength\":1},\"importance\":{\"type\":\"string\",\"enum\":[\"not important\",\"kind of important\",\"fairly important\",\"very important\",\"critical\"]}},\"required\":[\"fact\",\"importance\"],\"additionalProperties\":false}}}", PyJson.Compact(Fx.Tools()[1].OpenAiTool()));
            Assert.Equal("remember(fact, importance)", Fx.Tools()[1].Signature());
            Assert.Equal("{\"type\":\"function\",\"function\":{\"name\":\"set_mood\",\"description\":\"Feelings.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"target\":{\"type\":\"string\",\"enum\":[\"Pip\",\"Lux\"]},\"delta\":{\"type\":\"string\",\"enum\":[\"much worse\",\"worse\",\"a little worse\",\"no change\",\"a little better\",\"better\",\"much better\"]}},\"required\":[\"target\",\"delta\"],\"additionalProperties\":false}}}", PyJson.Compact(Fx.Tools()[2].OpenAiTool()));
            Assert.Equal("set_mood(target, delta)", Fx.Tools()[2].Signature());
            Assert.Equal("{\"type\":\"function\",\"function\":{\"name\":\"count\",\"description\":\"A number.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"n\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":5}},\"required\":[\"n\"],\"additionalProperties\":false}}}", PyJson.Compact(Fx.Tools()[3].OpenAiTool()));
            Assert.Equal("count(n)", Fx.Tools()[3].Signature());
            Assert.Equal("{\"type\":\"function\",\"function\":{\"name\":\"do_nothing\",\"description\":\"Nothing.\",\"parameters\":{\"type\":\"object\",\"properties\":{},\"required\":[],\"additionalProperties\":false}}}", PyJson.Compact(Fx.Tools()[4].OpenAiTool()));
            Assert.Equal("do_nothing()", Fx.Tools()[4].Signature());
            Assert.Equal("{\"type\":\"function\",\"function\":{\"name\":\"pick\",\"description\":\"Pick \\\"one\\\"; \\\\ here.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"who\":{\"type\":\"string\",\"enum\":[\"Pip\",\"Lux \\\"the\\\" fox\",\"Zo\u00eb\\\\x\",\"\u65e5\u672c\"],\"description\":\"who\"},\"size\":{\"type\":\"integer\",\"minimum\":-5,\"maximum\":60},\"mood\":{\"type\":\"string\",\"enum\":[\"so-so\",\"grand\"]},\"note\":{\"type\":\"string\",\"maxLength\":7,\"minLength\":1,\"description\":\"a note\"},\"big\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":39}},\"required\":[\"who\",\"size\"],\"additionalProperties\":false}}}", PyJson.Compact(Fx.OddTools()[0].OpenAiTool(), false));
            Assert.Equal("pick(who, size, mood?, note?, big?)", Fx.OddTools()[0].Signature());
        }

