            Assert.Null(chg.Parse(PyJson.Loads("\"importance 4\"")));
            Assert.Null(imp.Parse(PyJson.Loads("\"4 importance\"")));
            Assert.Null(chg.Parse(PyJson.Loads("\"4 importance\"")));
            Assert.Equal((int?)5, imp.Parse(PyJson.Loads("\"quite critical\"")));
            Assert.Null(chg.Parse(PyJson.Loads("\"quite critical\"")));
            Assert.Null(imp.Parse(PyJson.Loads("\"barely better\"")));
            Assert.Equal((int?)1, chg.Parse(PyJson.Loads("\"barely better\"")));
            Assert.Null(imp.Parse(PyJson.Loads("\"a bit worse than better\"")));
            Assert.Equal((int?)-1, chg.Parse(PyJson.Loads("\"a bit worse than better\"")));
            Assert.Null(imp.Parse(PyJson.Loads("\"kind\"")));
            Assert.Null(chg.Parse(PyJson.Loads("\"kind\"")));
            Assert.Null(imp.Parse(PyJson.Loads("\"bit\"")));
            Assert.Null(chg.Parse(PyJson.Loads("\"bit\"")));
            Assert.Equal("not important", imp.ToWords(-20.0)); Assert.Equal("much worse", chg.ToWords(-20.0));
            Assert.Equal("not important", imp.ToWords(-3.0)); Assert.Equal("much worse", chg.ToWords(-3.0));
            Assert.Equal("not important", imp.ToWords(-0.4)); Assert.Equal("no change", chg.ToWords(-0.4));
            Assert.Equal("not important", imp.ToWords(0.0)); Assert.Equal("no change", chg.ToWords(0.0));
            Assert.Equal("not important", imp.ToWords(0.4)); Assert.Equal("no change", chg.ToWords(0.4));
            Assert.Equal("not important", imp.ToWords(0.5)); Assert.Equal("no change", chg.ToWords(0.5));
            Assert.Equal("not important", imp.ToWords(1.5)); Assert.Equal("a little better", chg.ToWords(1.5));
            Assert.Equal("kind of important", imp.ToWords(2.5)); Assert.Equal("better", chg.ToWords(2.5));
            Assert.Equal("fairly important", imp.ToWords(3.5)); Assert.Equal("much better", chg.ToWords(3.5));
            Assert.Equal("critical", imp.ToWords(5.0)); Assert.Equal("much better", chg.ToWords(5.0));
            Assert.Equal("critical", imp.ToWords(6.0)); Assert.Equal("much better", chg.ToWords(6.0));
            Assert.Equal("critical", imp.ToWords(100.0)); Assert.Equal("much better", chg.ToWords(100.0));
            Assert.Equal("fairly important", imp.ToWords(2.9999)); Assert.Equal("much better", chg.ToWords(2.9999));
        }

        [Fact]
        public void ParseTextMatchesPython()
        {
            var names = new HashSet<string> { "say", "remember", "set_mood", "count", "do_nothing" };
            void Chk(string text, string want) { var (s, why) = StepParser.ParseText(text, names); Assert.Equal(want, s == null ? "NONE|" + why : s.Kind + "|" + s.Tool + "|" + (s.Args == null ? "null" : PyJson.Dumps(s.Args)) + "|" + s.Text + "|" + s.Salvaged); }
            Chk("{\"tool\": \"say\", \"args\": {\"line\": \"a\"}}", "call|say|{\"line\": \"a\"}||");
            Chk("{\"remember\": {\"fact\": \"x\", \"importance\": 3}}", "call|remember|{\"fact\": \"x\", \"importance\": 3}||tool name as key");
            Chk("Sure! {\"done\": true} hope that helps", "done||null||json inside other text");
            Chk("call:say{line:<|\"|>hey, you<|\"|>}", "call|say|{\"line\": \"hey, you\"}||gemma raw call syntax");
            Chk("hello there", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("", "NONE|the reply was empty");
            Chk("   ", "NONE|the reply was empty");
            Chk("{}", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("[]", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("null", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("{\"done\": 1}", "done||null||");
            Chk("{\"done\": \"true\"}", "done||null||");
            Chk("{\"done\": true, \"x\": 1}", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("{\"done\": false}", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("{\"final\": \"hi\"}", "final||null|hi|");
            Chk("{\"say\": \"hi\"}", "final||null|hi|");
            Chk("{\"reply\": \"hi\"}", "final||null|hi|");
            Chk("{\"final\": 5}", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("{\"final\": \"hi\", \"x\": 1}", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("{\"tool\": \"say\", \"args\": {\"line\": \"x\"}}", "call|say|{\"line\": \"x\"}||");
            Chk("{\"tool\": \"say\", \"arguments\": \"{\\\"line\\\": \\\"x\\\"}\"}", "call|say|{\"line\": \"x\"}||");
            Chk("{\"tool\": \"say\", \"arguments\": \"not json\"}", "call|say|\"not json\"||");
            Chk("{\"name\": \"say\", \"line\": \"direct\"}", "call|say|{\"line\": \"direct\"}||");
            Chk("{\"function\": \"say\", \"parameters\": {\"line\": \"p\"}}", "call|say|{\"line\": \"p\"}||");
            Chk("{\"tool_name\": \"count\", \"n\": 3}", "call|count|{\"n\": 3}||");
            Chk("{\"tool\": \"say\", \"args\": null}", "call|say|null||");
            Chk("{\"tool\": \"say\"}", "call|say|{}||");
            Chk("{\"tool_call\": {\"tool\": \"say\", \"args\": {\"line\": \"n\"}}}", "call|say|{\"line\": \"n\"}||");
            Chk("{\"call\": {\"name\": \"count\", \"n\": 2}}", "call|count|{\"n\": 2}||");
            Chk("{\"function_call\": {\"tool\": \"say\"}}", "call|say|{}||");
            Chk("{\"tool\": 5}", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("{\"tool\": \"unknown\", \"args\": {}}", "call|unknown|{}||");
            Chk("```json\n{\"tool\": \"count\", \"args\": {\"n\": 2}}\n```", "call|count|{\"n\": 2}||json inside other text");
            Chk("```\n{\"done\": true}\n```", "done||null||json inside other text");
            Chk("Here: {\"tool\": \"say\", \"args\": {\"line\": \"a {b} c\"}} done", "call|say|{\"line\": \"a {b} c\"}||json inside other text");
            Chk("x {\"a\": } y {\"done\": true}", "done||null||json inside other text");
            Chk("{\"done\": true} {\"final\": \"x\"}", "done||null||json inside other text");
            Chk("prefix {\"remember\": {\"fact\": \"q\"}}", "call|remember|{\"fact\": \"q\"}||json inside other text");
            Chk("<|tool_call>call:say{line:<|\"|>hi<|\"|>}<tool_call|>", "call|say|{\"line\": \"hi\"}||gemma raw call syntax");
            Chk("say{line:<|\"|>Hi there.<|\"|>}", "call|say|{\"line\": \"Hi there.\"}||gemma raw call syntax");
            Chk("count{n:3}", "call|count|{\"n\": 3}||gemma raw call syntax");
            Chk("count{n:3,}", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("count{}", "call|count|{}||gemma raw call syntax");
            Chk("count{ }", "call|count|{}||gemma raw call syntax");
            Chk("nope{x:1}", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("call:set_mood{target:<|\"|>Pip<|\"|>,delta:<|\"|>worse<|\"|>}", "call|set_mood|{\"target\": \"Pip\", \"delta\": \"worse\"}||gemma raw call syntax");
            Chk("say {line: <|\"|>spaced<|\"|>} trailing", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("say{line:<|\"|>a<|\"|>} more text", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("\u0000\u0001", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("\u00e9\u00e9\u00e9\u00e9\u00e9", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("{\"tool\": \"say\", \"args\": [1]}", "call|say|[1]||");
            Chk("{\"say\": {\"line\": \"x\"}}", "call|say|{\"line\": \"x\"}||tool name as key");
            Chk("{\"remember\": {}}", "call|remember|{}||tool name as key");
            Chk("{\"remember\": {\"a\": 1}, \"b\": 2}", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("{\"tool\":\"say\",\"args\":{\"line\":\"\\u00e9\\ud83d\\ude00\"}}", "call|say|{\"line\": \"\\u00e9\\ud83d\\ude00\"}||");
            Chk("say{line:<|\"|>x<|\"|>", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("  {\"done\": true}  ", "done||null||");
            Chk("{\"done\": true}}", "done||null||json inside other text");
            Chk("\"just a string\"", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("5", "NONE|the reply was not one JSON object of the allowed forms");
            Chk("{\"tool\": \"say\", \"args\": {\"line\": NaN}}", "call|say|{\"line\": NaN}||");
        }

